"""
Complete Knowledge Base Seed Generator across all 6 roles:
Backend, Frontend, Full Stack, Data, DevOps/Cloud, Mobile.
Generates >= 30 curated topics per role (5 Junior, 18 Mid, 6 Senior, 3 Staff) = 192 total items.
Outputs directly to backend/data/knowledge_base_seed.json (§Q3).
"""

import json
import os
from typing import Any, Dict, List


def create_kb_item(
    role: str,
    seniority: str,
    topic: str,
    subtopic: str,
    core_concepts: List[str],
    expected_depth: str,
    sample_questions: List[str],
    rubric_hints: List[str],
    tags: List[str],
) -> Dict[str, Any]:
    search_text = (
        f"Role: {role}. Seniority: {seniority}. Topic: {topic} - {subtopic}. "
        f"Concepts: {', '.join(core_concepts)}. Depth: {expected_depth}. "
        f"Tags: {', '.join(tags)}."
    )
    return {
        "role": role,
        "seniority": seniority,
        "topic": topic,
        "subtopic": subtopic,
        "core_concepts": core_concepts,
        "expected_depth": expected_depth,
        "sample_questions": sample_questions,
        "rubric_hints": rubric_hints,
        "tags": tags,
        "search_text": search_text,
    }


