def generate_all_kb_items() -> List[Dict[str, Any]]:
    all_items: List[Dict[str, Any]] = []
    backend = get_backend_items()
    frontend = get_frontend_items()
    fullstack = get_fullstack_items()
    data = get_data_items()
    devops = get_devops_items()
    mobile = get_mobile_items()

    all_items.extend(backend)
    all_items.extend(frontend)
    all_items.extend(fullstack)
    all_items.extend(data)
    all_items.extend(devops)
    all_items.extend(mobile)

    print(f"Backend count: {len(backend)}")
    print(f"Frontend count: {len(frontend)}")
    print(f"Full Stack count: {len(fullstack)}")
    print(f"Data count: {len(data)}")
    print(f"DevOps/Cloud count: {len(devops)}")
    print(f"Mobile count: {len(mobile)}")
    print(f"Total KB Items: {len(all_items)}")

    return all_items


if __name__ == "__main__":
    out_dir = os.path.join(os.path.dirname(__file__), "..", "data")
    os.makedirs(out_dir, exist_ok=True)
    out_path = os.path.join(out_dir, "knowledge_base_seed.json")

    items = generate_all_kb_items()
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(items, f, indent=2)

    print(f"Successfully generated {len(items)} KB items to {out_path}")
